"""Teaching-only native API/etcd fixture; copied into trusted question checks."""
import contextlib,json,os,re,shutil,socket,ssl,subprocess,tempfile,threading,time,urllib.error,urllib.parse,urllib.request
from pathlib import Path

class ControlPlane:
    def __init__(self):
        assert os.name=='posix' and os.getuid()!=0,'requires an isolated non-root Linux workspace'
        self.binaries={name:shutil.which(name) for name in ('etcd','kube-apiserver','kubectl','openssl')}
        assert all(self.binaries.values()),'native API fixture dependency missing'
        self.folder=tempfile.TemporaryDirectory(prefix='opsforge-apiserver-');self.root=Path(self.folder.name)
        self.children=[];self.logs=[];self.samples=[];self.alarms=[];self.stopped=threading.Event();self.started=time.monotonic()
        self.configs={};self.contexts={}
        # This overrides all normal Kubernetes environment discovery for child tools.
        self.env={k:v for k,v in os.environ.items() if not k.startswith('KUBERNETES_') and k!='KUBECONFIG' and k.lower() not in ('http_proxy','https_proxy','all_proxy')}
        self.env.update(HOME=str(self.root),KUBECONFIG=str(self.root/'never-use-global-kubeconfig'),GOMAXPROCS='1',GOGC='50',GOMEMLIMIT='256MiB',NO_PROXY='127.0.0.1,localhost')
        self.memory_file=next((p for p in (Path('/sys/fs/cgroup/opsforge-validation/memory.current'),Path('/sys/fs/cgroup/memory.current')) if p.is_file()),None)
        assert self.memory_file,'cgroup memory accounting required for API exercise'
        ports=[]
        while len(ports)<3:
            with socket.socket() as s:s.bind(('127.0.0.1',0));port=s.getsockname()[1]
            if port>=1024 and port not in ports:ports.append(port)
        self.api_port,self.client_port,self.peer_port=ports
        self.url='https://127.0.0.1:'+str(self.api_port)
    def command(self,args,timeout=10,input=None):
        self.check_budget()
        return subprocess.run(args,cwd=self.root,env=self.env,input=input,text=True,capture_output=True,timeout=timeout)
    def openssl(self,*args):
        r=self.command([self.binaries['openssl'],*args]);assert r.returncode==0,r.stderr[-600:]
    def make_certificate(self,name,subject,usage,extra=''):
        assert re.fullmatch('[a-z][a-z0-9-]{0,30}',name)
        self.openssl('req','-new','-newkey','rsa:2048','-nodes','-keyout',name+'.key','-out',name+'.csr','-subj',subject)
        (self.root/(name+'.ext')).write_text('basicConstraints=CA:FALSE\nkeyUsage=digitalSignature,keyEncipherment\nextendedKeyUsage='+usage+'\n'+extra)
        self.openssl('x509','-req','-in',name+'.csr','-CA','ca.crt','-CAkey','ca.key','-CAcreateserial','-out',name+'.crt','-days','1','-extfile',name+'.ext')
    def identity(self,name,groups=()):
        assert re.fullmatch('[a-z][a-z0-9-]{0,30}',name)
        if name not in self.contexts:
            assert all(re.fullmatch('[a-zA-Z0-9:_-]+',g) for g in groups)
            self.make_certificate(name,'/CN='+name+''.join('/O='+g for g in groups),'clientAuth')
            ctx=ssl.create_default_context(cafile=str(self.root/'ca.crt'));ctx.load_cert_chain(str(self.root/(name+'.crt')),str(self.root/(name+'.key')))
            self.contexts[name]=ctx
            config={'apiVersion':'v1','kind':'Config','clusters':[{'name':'exercise','cluster':{'server':self.url,'certificate-authority':str(self.root/'ca.crt')}}],'users':[{'name':name,'user':{'client-certificate':str(self.root/(name+'.crt')),'client-key':str(self.root/(name+'.key'))}}],'contexts':[{'name':'exercise','context':{'cluster':'exercise','user':name,'namespace':'training'}}],'current-context':'exercise'}
            f=self.root/(name+'.kubeconfig');f.write_text(json.dumps(config));self.configs[name]=f
        return name
    def start_process(self,name,args,limit='256MiB'):
        log=(self.root/(name+'.log')).open('w');self.logs.append(log)
        p=subprocess.Popen(args,cwd=self.root,env={**self.env,'GOMEMLIMIT':limit},stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
        self.children.append(p);return p
    def check_budget(self):
        if self.alarms:raise RuntimeError('Native API exercise stopped: '+self.alarms[0])
        if time.monotonic()-self.started>95:raise RuntimeError('Native API exercise deadline')
    def monitor(self):
        while not self.stopped.wait(.15):
            value=int(self.memory_file.read_text());self.samples.append(value)
            if value>650*1024**2 or time.monotonic()-self.started>95:
                self.alarms.append('memory_above_650MiB' if value>650*1024**2 else '95_second_deadline')
                for p in self.children:
                    if p.poll() is None:p.terminate()
                return
    def request(self,method,path,body=None,user='admin',content_type='application/json',headers=None):
        self.check_budget();assert path.startswith('/') and not path.startswith('//')
        assert user in self.contexts,'unknown isolated identity'
        data=None if body is None else json.dumps(body,separators=(',',':')).encode()
        h={'Content-Type':content_type,**(headers or {})}
        req=urllib.request.Request(self.url+path,data=data,method=method,headers=h)
        try:
            opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),urllib.request.HTTPSHandler(context=self.contexts[user]))
            with opener.open(req,timeout=5) as r:status=r.status;raw=r.read()
        except urllib.error.HTTPError as e:status=e.code;raw=e.read()
        try:result=json.loads(raw)
        except ValueError:result=raw.decode()
        return status,result
    def apply(self,path,obj,manager,force=False,user='admin'):
        query=urllib.parse.urlencode({'fieldManager':manager,'force':str(force).lower()})
        return self.request('PATCH',path+'?'+query,obj,user,'application/apply-patch+yaml')
    def create(self,path,obj,user='admin'):
        status,result=self.request('POST',path,obj,user);assert status==201,(status,result);return result
    def get(self,path,user='admin'):
        status,result=self.request('GET',path,user=user);assert status==200,(status,result);return result
    def kubectl(self,*args,user='admin',input=None):
        return self.command([self.binaries['kubectl'],'--kubeconfig='+str(self.configs[user]),'--context=exercise','--request-timeout=5s',*args],input=input)
    def wait_crd(self,name):
        until=time.monotonic()+10
        while time.monotonic()<until:
            obj=self.get('/apis/apiextensions.k8s.io/v1/customresourcedefinitions/'+name)
            if any(c.get('type')=='Established' and c.get('status')=='True' for c in ((obj.get('status') or {}).get('conditions') or [])):return obj
            time.sleep(.15)
        raise AssertionError('CRD did not become Established')
    def __enter__(self):
        self.thread=threading.Thread(target=self.monitor,daemon=True);self.thread.start()
        try:
            self.openssl('req','-x509','-newkey','rsa:2048','-nodes','-keyout','ca.key','-out','ca.crt','-days','1','-subj','/CN=OpsForge isolated API teaching CA')
            self.make_certificate('server','/CN=localhost','serverAuth','subjectAltName=DNS:localhost,IP:127.0.0.1\n')
            self.identity('admin',('system:masters',));self.openssl('genrsa','-out','sa.key','2048')
            etcd=self.start_process('etcd',[self.binaries['etcd'],'--name=training','--data-dir='+str(self.root/'etcd-data'),'--listen-client-urls=http://127.0.0.1:'+str(self.client_port),'--advertise-client-urls=http://127.0.0.1:'+str(self.client_port),'--listen-peer-urls=http://127.0.0.1:'+str(self.peer_port),'--initial-advertise-peer-urls=http://127.0.0.1:'+str(self.peer_port),'--initial-cluster=training=http://127.0.0.1:'+str(self.peer_port),'--quota-backend-bytes=33554432','--logger=zap','--log-level=error'],'128MiB')
            until=time.monotonic()+10
            while time.monotonic()<until:
                self.check_budget();assert etcd.poll() is None,'isolated etcd exited'
                try:
                    with urllib.request.build_opener(urllib.request.ProxyHandler({})).open('http://127.0.0.1:'+str(self.client_port)+'/health',timeout=.5) as r:
                        if json.load(r)['health']=='true':break
                except Exception:time.sleep(.1)
            else:raise RuntimeError('isolated etcd readiness timeout')
            server=self.start_process('apiserver',[self.binaries['kube-apiserver'],'--bind-address=127.0.0.1','--advertise-address=127.0.0.1','--secure-port='+str(self.api_port),'--etcd-servers=http://127.0.0.1:'+str(self.client_port),'--service-cluster-ip-range=10.253.0.0/24','--authorization-mode=RBAC','--anonymous-auth=false','--client-ca-file='+str(self.root/'ca.crt'),'--tls-cert-file='+str(self.root/'server.crt'),'--tls-private-key-file='+str(self.root/'server.key'),'--service-account-key-file='+str(self.root/'sa.key'),'--service-account-signing-key-file='+str(self.root/'sa.key'),'--service-account-issuer='+self.url,'--allow-privileged=false','--profiling=false','--max-requests-inflight=20','--max-mutating-requests-inflight=10','--v=0'])
            until=time.monotonic()+40
            while time.monotonic()<until:
                self.check_budget()
                assert server.poll() is None,'isolated API server exited: '+(self.root/'apiserver.log').read_text()[-700:]
                try:
                    status,text=self.request('GET','/readyz')
                    if status==200 and text.strip()=='ok':break
                except (urllib.error.URLError,TimeoutError):pass
                time.sleep(.15)
            else:raise RuntimeError('isolated API server readiness timeout')
            self.create('/api/v1/namespaces',{'apiVersion':'v1','kind':'Namespace','metadata':{'name':'training'}})
            return self
        except BaseException:
            self.close();raise
    def close(self):
        for p in reversed(self.children):
            if p.poll() is None:p.terminate()
        for p in reversed(self.children):
            try:p.wait(timeout=5)
            except subprocess.TimeoutExpired:p.kill();p.wait(timeout=3)
        self.stopped.set()
        if hasattr(self,'thread'):self.thread.join(timeout=2)
        for handle in self.logs:handle.close()
        remaining=[p.pid for p in self.children if p.poll() is None]
        self.folder.cleanup()
        print(json.dumps({'envtest_fixture':'v1.34.1','etcd':'3.6.4','peak_cgroup_bytes':max(self.samples,default=0),'elapsed_seconds':round(time.monotonic()-self.started,2),'alarms':self.alarms,'remaining_children':remaining,'no_controllers_or_nodes':True}),flush=True)
        assert not remaining
    def __exit__(self,typ,value,tb):
        self.close()
        if self.alarms:raise RuntimeError('Native API environment resource/deadline limit: '+self.alarms[0])
        return False
